import{_ as e,c as a,a2 as p,o as _}from"./chunks/framework.CqbvlPrP.js";const m=JSON.parse('{"title":"第二百六十七章 正觉者与智慧解脱者的区别","description":"","frontmatter":{},"headers":[],"relativePath":"meditation/巴利文大藏经/267第二百六十七章 正觉者与智慧解脱者的区别.md","filePath":"meditation/巴利文大藏经/267第二百六十七章 正觉者与智慧解脱者的区别.md"}'),o={name:"meditation/巴利文大藏经/267第二百六十七章 正觉者与智慧解脱者的区别.md"};function r(n,t,i,s,d,c){return _(),a("div",null,t[0]||(t[0]=[p('<h1 id="第二百六十七章-正觉者与智慧解脱者的区别" tabindex="-1">第二百六十七章 正觉者与智慧解脱者的区别 <a class="header-anchor" href="#第二百六十七章-正觉者与智慧解脱者的区别" aria-label="Permalink to &quot;第二百六十七章 正觉者与智慧解脱者的区别&quot;">​</a></h1><p>完全读懂巴利文大藏经</p><p>相应部22相应58经/遍正觉者经(蕴相应/蕴篇/修多罗)</p><p>有个时候，佛陀住在舍卫城的祇树林给孤独园，有一天，佛陀对出家弟子们说：“比丘们（出家人），已经证悟无上正等正觉的圣者们，他们已经不会再去执着和挂念世间一切的物质事物、物质身体、感受、念想、行为、认识、分别、判断了，他们已经除灭对世间一切物质事物、物质身体、感受、念想、行为、认识、分别、判断的贪欲、渴爱了，他们已经灭尽一切的烦恼和痛苦了。他们由于不沉迷于世间一切的物质事物、物质身体、感受、念想、行为、认识、分别、判断之中的缘故，不执着和挂念世间一切物质事物、物质身体、感受、念想、行为、认识、分别、判断的缘故而从世间完全的解脱出来。他们被称为：「已经证悟无上正等正觉解脱果位的圣者」。</p><p>比丘们！那些通过开启智慧证悟解脱果位的修行人，他们也已经不会再去执着和挂念世间一切的物质事物、物质身体、感受、念想、行为、认识、分别、判断了，他们也已经除灭对世间一切物质事物、物质身体、感受、念想、行为、认识、分别、判断的贪欲、渴爱了，他们也已经灭尽一切的烦恼和痛苦了。他们也由于不沉迷于世间一切的物质事物、物质身体、感受、念想、行为、认识、分别、判断之中的缘故，不执着和挂念世间一切物质事物、物质身体、感受、念想、行为、认识、分别、判断的缘故而从世间完全的解脱出来。他们被称为：「由开启智慧而证悟解脱果位的圣者」。</p><p>比丘们！证悟无上正等正觉解脱果位的圣者与由开启智慧而证悟解脱果位的圣者，他们之间有什么不同呢？简单的说就是：无上正觉者与智慧解脱者有什么不同呢？”</p><p>出家弟子们回答：“世尊，您说的正法是我们修行的根本，您是我们修行的引路人，是您慈悲的教导我们，我们才知道如何去修行的，我们以世尊您为皈依。世尊，如果您能为我们解说：无上正觉者与智慧解脱者有什么不同。我们就会时刻忆念您的教导，并按您所说的去修行的，恭请世尊您为我们说法。”</p><p>佛陀说：“比丘们！已经证悟无上正等正觉解脱果位的圣者们，他们通过自己的实践修行证悟去创立、建立修行的方法，开辟出一条通向解脱的大道，让世间的人明白这些修行的方法，让世间的人能够走上解脱的大道；他们对世间的众生宣讲、讲解除灭烦恼和痛苦的修行方法，宣讲、讲解从生死轮回中永远解脱出来的修行方法。已经证悟无上正等正觉解脱果位的圣者们，他们知道世间的真相、规则，他们由世间的真相、规则创立、建立出从世间彻底解脱出来的修行方法，他们熟悉世间的真相、规则，他们熟悉各种清净解脱的境界。简单的说就是：无上正觉者通过自己的实践修行证悟创立、建立出修行的方法，让世间的众生通过修行他们创立、建立的修行方法，循序渐进的从世间彻底的解脱出来。</p><p>比丘们！由开启智慧而证悟解脱果位的圣者们，他们按照无上正觉者创立、建立的修行方法去实践的修行，才逐渐的开启智慧，证悟各种清净的解脱境界的，他们是由实践修习无上正觉者创立、建立的修行方法而灭尽一切烦恼和痛苦，证悟解脱果位的。简单的说就是：智慧解脱者，他们是沿着无上正觉者创立、建立的修行方法去实践的修行，才灭尽一切烦恼和痛苦，从世间彻底永远的解脱出来，证悟解脱果位的。</p><p>比丘们！这个就是无上正觉者与智慧解脱者之间的差别和不同。</p><p>比丘们！你们要明白无上正觉者们创立、建立的修行正法，是他们暂时安立出来的修行方法，你们证悟解脱果位后，连这些无上正觉者们创立、建立的修行正法都不要去执着和挂念。你们证悟解脱果位后，从生死轮回中永远解脱出来的时候，从世间彻底解脱出来的时候，连无上正觉者们创立、建立的修行正法都会灭除殆尽，你们证悟解脱果位的时候内心念想中都不会再生起这些修行正法。念想的生起，就是烦恼的生起。这些无上正觉者们创立、建立的修行正法也是烦恼，不过是用清净的烦恼来灭除污秽的烦恼而已。证悟解脱果位后，不可再执着和挂念无上正觉者们创立、建立的修行正法，不可再在内心中生起无上正觉者们创立、建立的修行正法。”</p><p>佛陀说法后，听法的出家弟子们都再次的顶礼佛陀，随喜赞叹佛陀说法的无量功德，他们都按着佛陀所说的法去修行。</p>',12)]))}const f=e(o,[["render",r]]);export{m as __pageData,f as default};
